#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int pattern_len = strlen(pattern);
    int string_len = strlen(string);
    int match = 0;
    for (int i = 0; i < string_len; i++) {
        if (pattern[0] == '*' || pattern[0] == '?') {
            if (pattern[0] == '*') {
                for (int j = 0; j <= string_len - i; j++) {
                    if (match_pattern(pattern + 1, string + i + j)) {
                        match = 1;
                        break;
                    }
                }
            } else {
                match = match_pattern(pattern + 1, string + i + 1);
            }
        } else if (pattern[0] == string[i]) {
            match = match_pattern(pattern + 1, string + i + 1);
        } else {
            match = 0;
            break;
        }
    }
    if (match) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}

int match_pattern(char *pattern, char *string) {
    if (*pattern == '\0') {
        return *string == '\0';
    }
    if (*pattern == '*') {
        return match_pattern(pattern + 1, string) || (*string != '\0' && match_pattern(pattern, string + 1));
    }
    if (*pattern == '?') {
        return *string != '\0' && match_pattern(pattern + 1, string + 1);
    }
    return *pattern == *string && match_pattern(pattern + 1, string + 1);
}
